import { createServerFn } from '@tanstack/react-start'
import { decodeProjectData, defaultProjectData, type ProjectData, type ProjectView } from '#/lib/project'
// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "Human edits drafts"
