// Prompt: "Human sees and opens drafts"
// Changes: Drafts for the app – open a draft with its project, list a project's drafts, record the viewed revision.
const draftIdInput = (d: { draftId: string }) => ({ draftId: str(obj(d).draftId, 'draftId', 64) })

/** The draft and its project; null when there is no such draft (an ended draft is returned, the UI says so). */
export const getDraftFn = createServerFn()
  .validator(draftIdInput)
  .handler(({ data }) => {
    const store = projectStore()
    const draft = store.getDraft(data.draftId)
    const project = draft && store.getProject(draft.projectId)
    return draft && project ? { project, draft } : null
  })

export const listDraftsFn = createServerFn()
  .validator(idInput)
  .handler(({ data }) => projectStore().listDrafts(data.id))

